    { id: 'industry',   name:{ en: 'Industry-specific',   id: 'Spesifik Industri' },    desc: { en: 'Composed from the career graph: what is moving in your target industry and why you belong in it.', id: 'Disusun dari peta karier: apa yang bergerak di industri tujuanmu dan mengapa kamu cocok di sana.' } },
    { id: 'closing',    name:{ en: 'Closing & your questions', id: 'Penutup & Pertanyaanmu' }, desc: { en: 'The last five minutes: closing strong and asking questions that show judgment.', id: 'Lima menit terakhir: menutup dengan kuat dan bertanya dengan penuh pertimbangan.' } }
